-- title: Expenses
-- description: Personal finances: accounts, categories, monthly budgets and 18 months of transactions. Income is positive, spending is negative.
--
-- Tables: accounts, categories, budgets, transactions
-- This file is read-only sample data for the SQL Lab. The app copies it into a
-- practice database, so your experiments never change this file.
-- Generated by tools/generate_datasets.py

PRAGMA foreign_keys = ON;

CREATE TABLE accounts (
    id   INTEGER PRIMARY KEY,
    name TEXT NOT NULL,
    kind TEXT NOT NULL CHECK (kind IN ('bank', 'card', 'cash'))
);

CREATE TABLE categories (
    id   INTEGER PRIMARY KEY,
    name TEXT NOT NULL UNIQUE,
    kind TEXT NOT NULL CHECK (kind IN ('income', 'expense'))
);

CREATE TABLE budgets (
    category_id    INTEGER PRIMARY KEY REFERENCES categories (id),
    monthly_amount REAL NOT NULL
);

CREATE TABLE transactions (
    id          INTEGER PRIMARY KEY,
    tx_date     TEXT NOT NULL,
    description TEXT NOT NULL,
    amount      REAL NOT NULL,           -- positive = money in, negative = money out
    category_id INTEGER NOT NULL REFERENCES categories (id),
    account_id  INTEGER NOT NULL REFERENCES accounts (id)
);




